#!/usr/bin/env python3
"""Import an explicit complete-source response-field review (e.g. P3 Raffles).
No implementation, test, or global-uniqueness credit is inferred from this manifest.
"""
import argparse,hashlib,json,sqlite3,datetime
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('--library',type=Path,default=Path(__file__).resolve().parents[1].parent/'Singapore Maths Paper Library');p.add_argument('--revision',default='1');p.add_argument('--namespace');p.add_argument('--image-prefix');a=p.parse_args();raw=a.manifest.read_bytes();m=json.loads(raw);entries=m['entries'];db=sqlite3.connect(a.library/'coverage/ledger.sqlite');db.row_factory=sqlite3.Row;matches=list(db.execute('SELECT * FROM papers WHERE file_sha=?',(m['sourceSHA256'],)));assert matches,'Source hash absent from canonical library';paper=matches[0];assert hashlib.sha256(Path(m['sourcePath']).read_bytes()).hexdigest()==paper['file_sha'];existing={r[0] for r in db.execute('SELECT event_id FROM events')};timestamp=datetime.datetime.now(datetime.timezone.utc).isoformat();hashfile=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();base={'path':str(a.manifest.resolve()),'sha256':hashlib.sha256(raw).hexdigest()};events=[];prefix='reviewed-fields-'+paper['paper_id'];namespace=a.namespace or {'79c1903cf02bf7a9':'pilot:p3-rg25:','95d75c946fbfbc5a':'pilot:p4-ny25:'}.get(paper['paper_id']);assert namespace and namespace.endswith(':'),'Supply explicit --namespace for new source';image_prefix=a.image_prefix or {'79c1903cf02bf7a9':'raffles-','95d75c946fbfbc5a':'page-'}.get(paper['paper_id']);assert image_prefix,'Supply --image-prefix for the source renders';assert sorted(m['reviewedPages'])==list(range(1,paper['page_count']+1)),'Complete-source importer requires every physical page reviewed'
assert len(entries)==m.get('responseUnitCount',len(entries));assert sum(e.get('sourceFieldCount',1) for e in entries)==m['answerFieldCount'],'Response units and physical answer fields must reconcile separately'
def add(suffix,typ,entity,ident,payload,images=()):
 eid=prefix+'-'+suffix+'-v'+a.revision
 if eid in existing:return
 evidence=[base]+[{'path':str(Path(i).resolve()),'sha256':hashfile(i)} for i in dict.fromkeys(images)]
 events.append({'schemaVersion':1,'eventId':eid,'type':typ,'entityType':entity,'entityId':ident,'recordedAt':timestamp,'reviewer':'source-review:browse_missions; ledger-import:content_syllabus_audit','evidence':evidence,'payload':payload})
add('source','source_integrity_reviewed','paper',paper['paper_id'],{'completeness':'complete','sourceRole':'mixed','notes':'All physical source pages visually reviewed; individual question defects remain explicit. Reviewed artifact and canonical library copy have identical SHA-256.','issues':m['sourceIssues'],'sourceArtifactAlias':m['sourcePath']})
folder=Path(entries[0]['evidenceImage']).parent
for page in m['reviewedPages']:
 image=folder/f'{image_prefix}{page:02}.png';assert image.is_file();fields=[x['id'] for x in entries if x['sourcePage']==page]
 add('page-'+str(page),'page_visually_reviewed','page',paper['file_sha']+':'+str(page),{'observations':'Source response fields '+', '.join(fields) if fields else 'Reviewed cover/instruction or answer-key page as part of the complete source inventory.','sourceReviewCounts':{'numberedQuestions':m['numberedQuestionCount'],'responseFields':m['answerFieldCount'],'responseUnits':len(entries)},'scope':'Complete page inspection, without inferring correctness of any answer key.'},[image])
groups={}
for part in entries:groups.setdefault(part['canonicalPatternId'],[]).append(part)
for key,parts in groups.items():
 if db.execute('SELECT 1 FROM patterns WHERE pattern_id=?',(namespace+key,)).fetchone():continue
 add('pattern-'+key,'pattern_registered','pattern',namespace+key,{'title':parts[0]['title'],'description':key,'structuralSignature':key,'sourceReviewPatternGrouping':'Grouped within this paper; distinctness across the full registry remains unreviewed.','adaptationIds':[x['adaptationId'] for x in parts]})
manual=[]
for part in entries:
 cid='manual:'+paper['paper_id']+':'+part['id'];manual.append(cid);image=part['evidenceImage'];incomplete=part['reviewStatus']=='source-incomplete/ambiguous';dependency=part.get('sourceDiagramDependency','uncertain');assert dependency in ['required','not-required','uncertain'];issues=[issue for issue in m['sourceIssues'] if issue['question']==part['sourceQuestion']]
 if not db.execute('SELECT 1 FROM candidates WHERE candidate_key=?',(cid,)).fetchone():add('create-'+part['id'],'candidate_created','candidate',cid,{'paperId':paper['paper_id'],'sourceSha256':paper['file_sha'],'sourcePages':[part['sourcePage']],'questionNumber':part['sourceField'],'reason':'Manual field inventory replaces heuristic OCR segmentation, preserving numbered question and response-field labels.','workingTranscription':part['title']+'; '+part['independentSourceSolution'],'unitType':'response-field'},[image])
 add('review-'+part['id'],'candidate_visually_reviewed','candidate',cid,{'sourceSha256':paper['file_sha'],'reviewedSourcePages':[part['sourcePage']],'completeness':'incomplete' if incomplete else 'complete','diagramDependency':dependency,'observations':part['independentSourceSolution'],'sourcePrintedQuestion':part['sourcePrintedQuestion'],'sourceField':part['sourceField'],'sourceFieldIds':part.get('sourceFieldIds',[part['sourceField']]),'sourceFieldCount':part.get('sourceFieldCount',1),'sourceExpected':part['sourceExpected'],'sourceAnswerCheck':{'keyCorrect':part['sourceAnswerKeyCorrect'],'independentSourceSolution':part['independentSourceSolution']},'sourceDefects':issues,'adaptationStatus':part['adaptationStatus']},[image])
 if not incomplete and dependency!='uncertain':
  add('map-'+part['id'],'pattern_mapped','candidate',cid,{'patternId':namespace+part['canonicalPatternId'],'relation':'same-structure','structuralRationale':part['title'],'sourceVariantRequirements':{'sourceField':part['sourceField'],'originalAdaptationId':part['adaptationId'],'sourceSolution':part['independentSourceSolution'],'sourceDiagramDependency':dependency},'implementationCredit':'None: source-to-structure mapping only; integration and independent test scope are separate.'},[image])
if m.get('sourceInventoryReplacesHeuristicOCRSegmentation') is True:
 raw=rows=list(db.execute('SELECT DISTINCT a.candidate_key FROM candidate_aliases a JOIN candidates c USING(candidate_key) WHERE a.paper_id=? AND c.manual=0',(paper['paper_id'],)))
 for row in raw:add('supersede-'+row['candidate_key'].split(':')[-1],'candidate_superseded','candidate',row['candidate_key'],{'paperId':paper['paper_id'],'completeManualInventory':True,'reason':m['segmentationNote'],'replacementCandidateIds':manual})
 add('inventory','paper_inventory_reviewed','paper',paper['paper_id'],{'confirmedQuestionIds':manual,'excludedCandidateIds':[r['candidate_key'] for r in raw],'questionCount':len(manual),'numberedQuestionCount':m['numberedQuestionCount'],'answerFieldCount':m['answerFieldCount'],'responseUnitCount':len(entries),'segmentationChecked':True,'incompleteSourceFields':[e['id'] for e in entries if e['reviewStatus']=='source-incomplete/ambiguous'],'scope':'Inventory reconciliation is complete; incomplete source fields are retained and prevent full source coverage.'})
out=a.library/'coverage/imports'/('response-review-'+paper['paper_id']+'.events.json');out.write_text(json.dumps(events,indent=2)+'\n');print(json.dumps({'eventFile':str(out),'events':len(events),'manualFields':len(entries),'numberedQuestions':m['numberedQuestionCount'],'unresolvedDiagramDependencies':sum(e.get('sourceDiagramDependency','uncertain')=='uncertain' for e in entries),'sourceIncompleteFields':[e['id'] for e in entries if e['reviewStatus']=='source-incomplete/ambiguous']}))
